  'error.code.aiRefused': ['AI가 이 요청을 거절했습니다. 주제를 바꿔 보세요.', 'The AI declined this request. Try another topic.'], 'error.code.aiCutOff': ['AI의 답이 중간에 끊겼습니다. 곡 구성을 짧게 해 보세요.', 'The answer was cut off. Try a shorter form.'],
  'error.code.aiOllamaOffline': ['Ollama에 연결할 수 없습니다. Ollama가 실행 중인지, 주소가 맞는지 확인하세요.', 'Cannot reach Ollama. Check that it runs and the address is right.'], 'error.code.aiOllamaModel': ['Ollama에 그 모델이 없습니다. "ollama pull 모델이름"으로 받으세요.', 'Ollama does not have that model. Run “ollama pull <model>”.'],
  'error.code.notSong': ['MyAudioMaker 곡 파일이 아닙니다.', 'Not a MyAudioMaker song file.'], 'error.code.cancelled': ['취소했습니다.', 'Cancelled.'],
