// Generated from the data tables: genres, moods, themes, forms, instrument categories, templates.
for (const g of GENRES) { T[`genre.${g.id}`] = [g.ko, g.en]; T[`template.${g.id}`] = [`${g.ko} 템플릿`, `${g.en} template`]; T[`template.${g.id}.desc`] = [`${g.ko} 반주와 코드 (가사 없음)`, `${g.en} band and chords (no lyrics)`]; }
for (const m of MOODS) T[`mood.${m.id}`] = [m.ko, m.en];
for (const th of THEMES) T[`theme.${th.id}`] = [th.ko, th.en];
for (const s of STRUCTURES) T[`structure.${s.id}`] = [s.ko, s.en];
for (const c of INSTRUMENT_CATEGORIES) T[`instcat.${c.id}`] = [c.ko, c.en];

export const ko = Object.fromEntries(Object.entries(T).map(([k, [a]]) => [k, a]));
export const en = Object.fromEntries(Object.entries(T).map(([k, [, b]]) => [k, b]));
